import java.io.*;
import java.util.*;

public class Main {
    static int mod = 998244353;

    static long fastPower(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long[] factorials;

    public static long nCr(int n, int k) {
        if (n < k) return 0;
        long numerator = factorials[n];
        long denominator = (factorials[n - k] * factorials[k]) % mod;
        return (numerator * fastPower(denominator, mod - 2)) % mod;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int maxSize = 200001;
        factorials = new long[maxSize];
        factorials[0] = 1;
        for (int i = 1; i < maxSize; i++) {
            factorials[i] = (factorials[i - 1] * i) % mod;
        }
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        long k = Long.parseLong(input[1]);
        if (k >= n) {
            pw.println(0);
            pw.flush();
            return;
        }
        if (k == 0) {
            pw.println(factorials[n]);
            pw.flush();
            return;
        }
        if (k == n - 1) {
            pw.println(2L * n);
            pw.flush();
            return;
        }
        int filledCols = (int) (n - k);
        long waysToChooseFilledCols = nCr(n, filledCols);
        long ans = 0;
        for (int emptyCols = 0; emptyCols <= filledCols; emptyCols++) {
            long waysToChoose = nCr(filledCols, emptyCols);
            long waysToFill = fastPower(filledCols - emptyCols, n);
            long val = (waysToChoose * waysToFill) % mod;
            if (emptyCols % 2 == 1) {
                val = (mod - val) % mod;
            }
            ans = (ans + val) % mod;
        }
        ans = (ans * waysToChooseFilledCols) % mod;
        ans = (ans * 2) % mod;
        pw.println(ans);
        pw.flush();
    }
}
